 const text=e.el('planningChainOverview').textContent;assert.match(text,/40 \/ 100/);assert.match(text,/4 → 2 чел/);assert.match(text,/Договор подрядчика/);assert.match(e.el('planningGantt').textContent,/Пик: 4/);assert.match(e.el('planningGantt').textContent,/факт 40 \/ 100/);
